<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\RelyingParty\Domain\ValueObject\Holder\RelyingPartyApiKeyAttributeHolder;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the RelyingPartyApiKeyAttributeHolder trait.
 *
 * Covers assignment, retrieval, default fallback,
 * transfer between holders, validation rules, and unset operations.
 */
class RelyingPartyApiKeyAttributeHolderUnitTest extends TestCase
{
    /**
     * Asserts that the code attribute is not assigned by default
     * and that getApiKey returns null on a freshly created holder.
     */
    public function testApiKeyNotAssignedByDefault(): void
    {
        // Arrange
        $holder = new ImplWithRelyingPartyApiKeyAttributeHolderUnitTest();

        // Assert
        $this->assertFalse($holder->isApiKeyAssigned());
        $this->assertNull($holder->getApiKey());
    }
}
class ImplWithRelyingPartyApiKeyAttributeHolderUnitTest
{
    use RelyingPartyApiKeyAttributeHolder;
    public function assertRules(ConstraintFailList $errorsList): self
    {
        $result = new self();
        $this->withAssertedApiKeyRules($result, $errorsList);
        return $result;
    }

    public function applyDefaults(): void
    {
        $this->withDefaultApiKey();
    }
}
